#!/usr/bin/env python3
"""Render reports/inventory/*.json into reports/firmware-inventory.md (machine-derived tables).

    gen_firmware_report.py <report_dir>
"""
import json
import re
import sys
from pathlib import Path

TELEPHONY = re.compile(r"radio|ims|telephony|qcril|iwlan|cne|uim|lpa|euicc|esim|sim|carrier|dpm|datachannel|"
                       r"qtidata|atfwd|embms|qmi|modem|mbn|sms|mms|dialer|telecom|stk|ons\b", re.I)
CAMERA = re.compile(r"camera|camx|chi|imager|motcam|arcsoft|dolbyvision|c2pa|aon\b", re.I)


def load(inv, name):
    return json.loads((inv / f"{name}.json").read_text(encoding="utf-8"))


def table(headers, rows):
    out = ["| " + " | ".join(headers) + " |", "|" + "---|" * len(headers)]
    out += ["| " + " | ".join(str(c).replace("|", "/") for c in row) + " |" for row in rows]
    return out


def main():
    rdir = Path(sys.argv[1])
    inv = rdir / "inventory"
    summary, props, packages = load(inv, "summary"), load(inv, "props"), load(inv, "packages")
    vintf, init, perms, classpath = load(inv, "vintf"), load(inv, "init"), load(inv, "permissions"), load(inv, "classpath")
    md = [f"# Firmware inventory: {summary['firmware']}", "",
          "Generated by `scripts/gen_firmware_report.py` from `reports/inventory/*.json`. Do not edit.", ""]

    md += ["## Partitions", ""]
    rows = []
    for name, p in summary["partitions"].items():
        if p.get("present"):
            rows.append([name, p["files"], f"{p['bytes'] / 2**20:.0f}", sum(p["packages"].values()), p["elf_objects"],
                         p["init_services"], p["vintf_files"], p.get("fingerprint") or ""])
    md += table(["Partition", "Files", "MiB", "APK/APEX", "ELF", "init services", "VINTF files", "Fingerprint"], rows)
    sup = summary.get("super", {})
    if sup:
        md += ["", f"Super: {sup['size']} bytes, LP metadata v{sup['lp_version']}, header flags {sup['header_flags']} "
               f"(1 = Virtual A/B), {sup['metadata_slots']} metadata slots.", ""]
        md += table(["Logical partition", "Size (bytes)", "Group", "Filesystem", "SHA-256"],
                    [[p["name"], p["size"], p["group"], p.get("filesystem") or "", (p.get("sha256") or "")[:16]]
                     for p in sup["partitions"]])

    md += ["", "## Key build properties", ""]
    keys = ["ro.build.version.release", "ro.build.version.sdk", "ro.build.version.sdk_full",
            "ro.build.version.security_patch", "ro.vendor.build.security_patch", "ro.board.platform",
            "ro.board.api_level", "ro.board.first_api_level", "ro.product.first_api_level", "ro.llndk.api_level",
            "ro.treble.enabled", "ro.apex.updatable", "ro.control_privapp_permissions",
            "ro.system.build.version.qcom", "ro.vendor.build.version.qcom", "persist.radio.multisim.config",
            "ro.telephony.default_network", "persist.vendor.data.iwlan.enable", "vendor.camera.aux.packagelist",
            "persist.vendor.camera.privapp.list", "ro.camera.cfa.packagelist"]
    rows = []
    for k in keys:
        for part, d in props.items():
            if k in d:
                rows.append([k, part, d[k]])
    md += table(["Property", "Set in", "Value"], rows)

    md += ["", "## Device HALs (vendor + odm VINTF manifests)", ""]
    hals = {}
    for part in ("vendor", "odm"):
        for doc in vintf.get(part, []):
            if doc["kind"] != "manifest":
                continue
            for h in doc["hals"]:
                e = hals.setdefault(h["name"], {"format": h["format"], "versions": set(), "instances": set()})
                e["versions"].update(h["versions"])
                e["instances"].update(f.split("/", 1)[-1] if "/" in f else f for f in h["fqnames"])
                for i in h["interfaces"]:
                    e["instances"].update(i["instances"])
    def area(n):
        return "telephony" if TELEPHONY.search(n) else "camera" if CAMERA.search(n) else ""
    rows = [[n, h["format"], ",".join(sorted(h["versions"])) or "-", ", ".join(sorted(h["instances"]))[:90], area(n)]
            for n, h in sorted(hals.items())]
    md += [f"{len(rows)} HALs declared.", ""] + table(["HAL", "Format", "Version", "Instances", "Area"], rows)

    md += ["", "## Framework classpath (stock system)", ""]
    rows = sorted({(j["classpath"], j["path"]) for jars in classpath.values() for j in jars
                   if j["classpath"] in ("BOOTCLASSPATH", "SYSTEMSERVERCLASSPATH")})
    md += table(["Classpath", "Jar"], rows)

    for title, pat in (("Telephony-related packages", TELEPHONY), ("Camera-related packages", CAMERA)):
        md += ["", f"## {title}", ""]
        rows = []
        for p in sorted(packages, key=lambda p: p["path"]):
            if p["kind"] in ("apex", "overlay") or not p.get("package"):
                continue
            if not (pat.search(p["package"]) or pat.search(p["path"])):
                continue
            libs = ", ".join(l["name"] for l in p.get("uses_libraries", []) if l.get("required", True) is not False)
            rows.append([p["package"], p["path"], p["cert_label"], p.get("sharedUserId") or "", libs[:80]])
        md += table(["Package", "Path", "Certificate", "sharedUserId", "Required shared libraries"], rows)

    md += ["", "## Signing certificates", ""]
    md += table(["Label", "Packages", "SHA-256 (first 16)", "Examples"],
                [[g["label"], g["count"], str(g["cert_sha256"])[:16], ", ".join(g["sample"][:4])]
                 for g in summary["certificates"][:20]])

    md += ["", "## Radio / IMS / camera init services (vendor)", ""]
    rows = [[s["name"], s["exec"], s["user"] or "", " ".join(s["class"]), ",".join(s["flags"]), s["rc"]]
            for s in init.get("vendor", [])
            if TELEPHONY.search(s["name"] + s["exec"]) or CAMERA.search(s["name"] + s["exec"])]
    md += table(["Service", "Executable", "User", "Class", "Flags", "rc file"], rows)

    out = rdir / "firmware-inventory.md"
    out.write_text("\n".join(md) + "\n", encoding="utf-8", newline="\n")
    print(f"{out}: {len(md)} lines")


if __name__ == "__main__":
    main()
